#[test]
fn actual_resource_functions_before_after() {
    let e = fixture();
    let root = e.path.clone();
    assert!(before::icon(&e).is_none());
    assert!(before::cmd(&e, &e.manifest).is_none());
    assert_eq!(
        after::icon(&e),
        Some(
            e.resource_path
                .join("resources/command-icon.png")
                .to_string_lossy()
                .into()
        )
    );
    assert!(after::cmd(&e, &e.manifest).is_some());
    assert_eq!(e.path, root);
    assert!(after::cmd(&e, &json!({"icon":"../secret"})).is_none());
}
#[test]
fn verified_exact_covered_aliases() {
    let mut ctx = CoreContext::default();
    let mut e = fixture();
    e.manifest = json!({"replaces":["com.tezbar.fixture","raycast.fixture"],"commands":[{"name":"run","runtime":"rust","platforms":["macOS"]}]});
    ctx.entries.push(e.clone());
    assert!(verified_alias(&ctx, "com.tezbar.fixture", "run")
        .unwrap()
        .is_none());
    ctx.verified.insert(e.id.clone(), e.manifest.clone());
    for id in ["com.tezbar.fixture", "raycast.fixture"] {
        assert_eq!(verified_alias(&ctx, id, "run").unwrap(), Some(e.id.clone()));
        assert!(verified_alias(&ctx, id, "uncovered").unwrap().is_none());
    }
    for id in [
        "COM.TEZBAR.fixture",
        "com.tezbar.fixture ",
        " com.tezbar.fixture",
        "raycast.fixture.evil",
    ] {
        assert!(verified_alias(&ctx, id, "run").unwrap().is_none());
    }
    let mut e2 = e.clone();
    e2.id = "com.tezbar.native.other".into();
    ctx.verified.insert(e2.id.clone(), e2.manifest.clone());
    ctx.entries.push(e2);
    assert!(verified_alias(&ctx, "com.tezbar.fixture", "run").is_err());
}

