                || s.contains(['\\', ':', '\0'])
                || s.chars().any(|c| c.is_control())
                || s.starts_with('/')
                || s.split('/')
                    .any(|p| p.is_empty() || p == "." || p == ".." || p.ends_with([' ', '.']))
